  "Accept final commission: capture {0}": "Zaakceptuj ostateczną prowizję: przechwyć {0}",
  "Accept surrender": "Zaakceptuj poddanie się",
  "Accept the commission": "Zaakceptuj prowizję",
  "accepted a Papal commission": "przyjął papieskie zlecenie",
  "Accepted delivery to {0}.": "Zaakceptowana dostawa do {0}.",
  "Accepted passage to {0}.": "Zaakceptowano przejście do {0}.",
  "Accuracy {0}% / Line break {1}% / Range {2}": "Dokładność {0}% / podział wiersza {1}% / zakres {2}",
  "ACCURACY {0}% LINE BREAK {1}% RANGE {2}": "DOKŁADNOŚĆ {0}% ZŁAMANIE LINII {1}% ZAKRES {2}",
